render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#ticker-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const tickerText = params.ticker_text !== undefined ? params.ticker_text : 'ÚLTIMA HORA: TRANSMISIÓN EN VIVO';
const separator = params.separator !== undefined ? params.separator : ' • ';
const badgeText = params.badge_text !== undefined ? params.badge_text : 'EN VIVO';
const showBadge = params.show_badge !== false;
const scrollSpeed = (params.scroll_speed || 1.5) * 80;
const moveLeft = params.direction_left !== false;

const yPct = Math.max(0, Math.min(100, params.y_position_pct !== undefined ? params.y_position_pct : 90)) / 100;
const barH = params.bar_height || 55;
const barY = (height - barH) * yPct;

const fontSize = params.font_size || 22;
const fontFamily = params.font_family || 'Segoe UI, Arial, sans-serif';

const barColor = params.bar_color || '#0D1117';
const barOpacity = params.bar_opacity !== undefined ? params.bar_opacity : 0.95;
const textColor = params.text_color || '#FFFFFF';
const separatorColor = params.separator_color || '#FFD700';
const badgeBg = params.badge_bg || '#E50914';
const badgeTextColor = params.badge_text_color || '#FFFFFF';
const showAccentLine = params.show_accent_line !== false;
const accentLineColor = params.accent_line_color || '#E50914';

// Clear screen / background
c.clearRect(0, 0, width, height);

// 1. DIBUJAR FONDO DE LA BARRA COMPLETA
c.save();
c.globalAlpha = barOpacity;
c.fillStyle = barColor;
c.fillRect(0, barY, width, barH);
c.restore();

// Línea de acento/borde
if (showAccentLine) {
  c.save();
  c.fillStyle = accentLineColor;
  const lineH = 3;
  const lineY = yPct > 0.5 ? barY : barY + barH - lineH;
  c.fillRect(0, lineY, width, lineH);
  c.restore();
}

// 2. MEDIR ETIQUETA FIJA (SI EXISTE)
let badgeW = 0;
if (showBadge && badgeText.trim().length > 0) {
  c.font = `bold ${Math.round(fontSize * 0.85)}px ${fontFamily}`;
  const textW = c.measureText(badgeText).width;
  badgeW = textW + 36;
}

// 3. DIBUJAR TEXTO DESLIZANTE (ÁREA RECORTADA)
const clipX = badgeW;
const clipW = width - badgeW;

if (clipW > 0 && tickerText.length > 0) {
  c.save();
  c.beginPath();
  c.rect(clipX, barY, clipW, barH);
  c.clip();

  c.font = `bold ${fontSize}px ${fontFamily}`;
  const mainTextW = c.measureText(tickerText).width;
  const sepW = c.measureText(separator).width;
  const unitW = mainTextW + sepW;

  if (unitW > 0) {
    const totalDist = time * scrollSpeed;
    const offset = totalDist % unitW;

    let startX = moveLeft ? (clipX - offset) : (clipX - unitW + offset);

    c.textBaseline = 'middle';
    const textY = barY + barH / 2;

    while (startX < clipX + clipW + unitW) {
      if (startX + unitW > clipX - unitW) {
        // Dibujar texto principal
        c.fillStyle = textColor;
        c.fillText(tickerText, startX, textY);

        // Dibujar separador con su propio color
        c.fillStyle = separatorColor;
        c.fillText(separator, startX + mainTextW, textY);
      }
      startX += unitW;
    }
  }
  c.restore();
}

// 4. DIBUJAR ETIQUETA FIJA ENCIMA
if (showBadge && badgeW > 0) {
  c.save();
  c.fillStyle = badgeBg;
  c.fillRect(0, barY, badgeW, barH);

  c.fillStyle = 'rgba(255, 255, 255, 0.25)';
  c.fillRect(badgeW - 3, barY, 3, barH);

  c.fillStyle = badgeTextColor;
  c.font = `bold ${Math.round(fontSize * 0.85)}px ${fontFamily}`;
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(badgeText, badgeW / 2, barY + barH / 2);
  c.restore();
}
